impl Solution {
    pub fn detect_capital_use(word: String) -> bool {
        let n = word.len();
        if n == 0 {
            return true;
        }

        let mut all_caps = true;
        let mut all_lower = true;
        let mut first_cap_rest_lower = true;

        for i in 0..n {
            let c = word.chars().nth(i).unwrap();
            if c.is_uppercase() {
                all_lower = false;
            } else {
                all_caps = false;
                if i > 0 {
                    first_cap_rest_lower = false;
                }
            }
        }

        if n > 1 {
            let first_char = word.chars().nth(0).unwrap();
            for i in 1..n {
                let c = word.chars().nth(i).unwrap();
                if first_char.is_uppercase() && !c.is_lowercase() {
                    first_cap_rest_lower = false;
                }
            }
        }

        all_caps || all_lower || first_cap_rest_lower
    }
}

